/* Usability layer: coordinates remain those of the official map. */
const mapParams=new URLSearchParams(location.search);
const originNote=document.createElement('p');originNote.className='origin-note';box.after(originNote);
const quick=document.createElement('div');quick.className='map-quick';quick.setAttribute('aria-label','Destinos rápidos');originNote.after(quick);
const hiddenDestinations=new Map();
for(const group of [...routeDestination.querySelectorAll('optgroup')])if(!['Salones','Servicios y áreas de apoyo'].includes(group.label)){for(const option of group.children)hiddenDestinations.set(option.value,option.cloneNode(true));group.remove();}
const entryOption=new Option('Entrada','entry');routeDestination.querySelector('optgroup[label="Servicios y áreas de apoyo"]').append(entryOption);
function selectDestination(value){if(![...routeDestination.options].some(o=>o.value===value)){const option=hiddenDestinations.get(value);if(!option)return;routeDestination.append(option.cloneNode(true));}routeDestination.value=value;recalculate();}
function addShortcut(label,value){const button=document.createElement('button');button.type='button';button.textContent=label;button.addEventListener('click',()=>selectDestination(value));quick.append(button);}
addShortcut('Baños','alias:area-banos');addShortcut('Acreditación','alias:area-acreditacion');addShortcut('Entrada','entry');
const nextDestination=mapParams.get('next');if(nextDestination&&[...routeDestination.options].some(o=>o.value===nextDestination))addShortcut('Mi próxima charla',nextDestination);
const sourceSelectSponsor=selectSponsor;selectSponsor=function(id){sourceSelectSponsor(id);const value='s:'+id;if(hiddenDestinations.has(value)){const button=document.createElement('button');button.className='primary';button.textContent='Cómo llegar a este stand';button.addEventListener('click',()=>{selectDestination(value);box.scrollIntoView({block:'start'});});infoPanel.append(button);}};
const sourceDestinationInfo=destinationInfo;destinationInfo=function(){return routeDestination.value==='entry'?routeOriginOptions.find(o=>o.value==='o:entry'):sourceDestinationInfo();};
const sourceEndpoints=renderEndpoints;renderEndpoints=function(){sourceEndpoints();if(routeDestination.value==='alias:area-banos'){const floor=originChosen?getOriginLoc().floor:null;document.querySelectorAll('.map-endpoint.destination').forEach(marker=>{const f=Number(marker.closest('[data-map-floor]').dataset.mapFloor),label='Baños · planta '+(f===1?'baja':'alta');marker.querySelector('span').textContent=label;marker.setAttribute('aria-label',label);marker.classList.toggle('preferred-bath',f===floor);marker.classList.toggle('other-bath',floor!==null&&f!==floor);});}};
let suggestedOrigin=mapParams.get('origin'),suggestedLabel=mapParams.get('originLabel');
try{const previous=JSON.parse(sessionStorage.getItem('congreso-map-origin-note')||'null');if(routeOrigin.value&&previous?.origin===routeOrigin.value){suggestedOrigin=previous.origin;suggestedLabel=previous.label;}else if(routeOrigin.value){suggestedOrigin=null;suggestedLabel=null;}}catch{}
if(!routeOrigin.value&&suggestedOrigin&&[...routeOrigin.options].some(o=>o.value===suggestedOrigin))routeOrigin.value=suggestedOrigin;
function refreshOriginNote(){const inferred=suggestedOrigin&&routeOrigin.value===suggestedOrigin;originNote.textContent=inferred?suggestedLabel:routeOrigin.value?'Origen elegido por ti · no es una ubicación GPS.':'Elige tu punto de partida; no detectamos tu ubicación.';try{if(inferred)sessionStorage.setItem('congreso-map-origin-note',JSON.stringify({origin:suggestedOrigin,label:suggestedLabel}));else sessionStorage.removeItem('congreso-map-origin-note');}catch{}}
routeOrigin.addEventListener('change',()=>{suggestedOrigin=null;suggestedLabel=null;refreshOriginNote();});
renderGuide=function(){guide.replaceChildren();};
function frameMap(){const destinations=[...document.querySelectorAll('.map-endpoint.destination')];if(!destinations.length)return;let targetZoom=180;const frames=[];document.querySelectorAll('[data-map-floor]').forEach(card=>{const svg=card.querySelector('svg'),vb=svg.viewBox.baseVal,paths=[...svg.querySelectorAll('.route-line')];let points=[];for(const path of paths){const b=path.getBBox();points.push([b.x,b.y],[b.x+b.width,b.y+b.height]);}if(!points.length)for(const marker of card.querySelectorAll('.map-endpoint.destination'))points.push([parseFloat(marker.style.left)*vb.width/100,parseFloat(marker.style.top)*vb.height/100]);if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),scroll=card.querySelector('.map-scroll');if(paths.length){targetZoom=Math.min(targetZoom,100*vb.width/Math.max(1,maxX-minX+110),100*scroll.clientHeight*vb.width/(Math.max(1,scroll.clientWidth)*(maxY-minY+80)));}frames.push({scroll,x:(minX+maxX)/2/vb.width,y:(minY+maxY)/2/vb.height});});
 setZoom(Math.floor(Math.max(100,Math.min(180,targetZoom))));requestAnimationFrame(()=>requestAnimationFrame(()=>{for(const f of frames){f.scroll.scrollLeft=f.x*f.scroll.scrollWidth-f.scroll.clientWidth/2;f.scroll.scrollTop=f.y*f.scroll.scrollHeight-f.scroll.clientHeight/2;}updateMapHeight();}));
}
recalculate=function(){clearRoute();guide.replaceChildren();originChosen=!!routeOrigin.value;hasRoute=false;const value=routeDestination.value,dest=destinationInfo(),origin=originChosen?getOriginLoc():null,baths=value==='alias:area-banos';highlightRoom(value.startsWith('r:')?value.slice(2):null);
 if(baths){drawBathrooms();routeStatus.textContent=origin?'Baños de tu planta resaltados. Se muestran también los de la otra planta.':'Baños en ambas plantas. Elige un origen para destacar los de esa planta.';}
 else if(origin&&value){if(value==='entry'){if(origin.floor===dest.floor)drawPolyline(routeLayer1,routeOnFloor(1,origin.coord,dest.coord));else routeAcrossFloors(origin,dest);}else showRoute();const paths=[...document.querySelectorAll('.route-line')];hasRoute=paths.length>0;const same=dest?.coord&&dest.floor===origin.floor&&dest.coord.every((n,i)=>n===origin.coord[i]);if(same){routeStatus.textContent='Origen y destino están en el mismo punto.';}else if(!hasRoute){routeStatus.textContent='No hay un recorrido disponible entre estos puntos. Consulta al personal del congreso; la conexión debe confirmarse.';}else if(dest&&origin.floor!==dest.floor){const side=(origin.floor===1?dest.stair:origin.stair)||'left';routeStatus.textContent=(origin.floor===1?'Sube a planta alta':'Baja a planta baja')+' por la escalera marcada en el '+(side==='left'?'lado izquierdo':'lado derecho')+' del plano.';}else routeStatus.textContent='Sigue el trazado en '+(origin.floor===1?'planta baja.':'planta alta.');}
 else routeStatus.textContent=value?'Destino marcado. Elige un origen para ver el recorrido.':'Elige un destino o usa un acceso rápido.';
 renderEndpoints();setFloor();clearRouteBtn.hidden=!originChosen;refreshOriginNote();frameMap();
};
// Restore a selected destination that may have belonged to a secondary group.
if(saved?.destination&&!routeDestination.value&&hiddenDestinations.has(saved.destination)){routeDestination.append(hiddenDestinations.get(saved.destination).cloneNode(true));routeDestination.value=saved.destination;}
recalculate();document.body.dataset.usabilityReady='true';
